// Generated by CLI Printing Press (https://github.com/mvanhorn/cli-printing-press). DO NOT EDIT.
// Hand-extended: store-backed listing with --type/--model filters when the
// corpus exists; falls back to the generated live sitemap fetch otherwise.

package cli

import (
	"fmt"

	"github.com/spf13/cobra"

	"github.com/mvanhorn/printing-press-library/library/devices/averusa/internal/averusa"
	"github.com/mvanhorn/printing-press-library/library/devices/averusa/internal/cliutil"
)

func newDocsListCmd(flags *rootFlags) *cobra.Command {
	var dbPath string
	var docType string
	var model string
	var limit int

	cmd := &cobra.Command{
		Use:         "list",
		Short:       "List the document catalog, optionally filtered by doc type",
		Example:     "  averusa-pp-cli docs list --type user-manual",
		Annotations: map[string]string{"pp:method": "GET", "pp:path": "https://averusa.my.site.com/support/s/sitemap-topicarticle-1.xml", "mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 && cmd.Flags().NFlag() == 0 {
				return cmd.Help()
			}
			if dryRunOK(flags) {
				return writeDryRun(cmd.OutOrStdout(), flags, "docs list")
			}
			// Store-backed path: serve from the corpus. A filtered query with
			// no matches returns the honest empty result (never a fall-through
			// to unrelated live data); --data-source local must never touch
			// the network. Only --data-source auto with NO filter flags falls
			// through to the live sitemap when the corpus is empty.
			if flags.dataSource != "live" {
				dbPath = corpusDBPath(dbPath)
				corpusPresent := !corpusMissing(cmd, flags, dbPath)
				if corpusPresent {
					ctx, cancel := boundCtx(cmd.Context(), flags)
					defer cancel()
					st, err := openCorpus(ctx, dbPath)
					if err != nil {
						return err
					}
					defer st.Close()
					if limit <= 0 {
						limit = 100
					}
					docs, err := st.ListAVERUSADocuments(docType, model, limit)
					if err != nil {
						return err
					}
					if len(docs) > 0 || docType != "" || model != "" || flags.dataSource == "local" {
						// Non-empty, or an explicitly filtered / local-only
						// query: empty is the correct answer, not live data.
						if len(docs) == 0 {
							fmt.Fprintf(cmd.ErrOrStderr(), "no documents%s%s in the corpus; run `averusa-pp-cli harvest` first\n",
								map[bool]string{true: " of type " + docType, false: ""}[docType != ""],
								map[bool]string{true: " for model " + model, false: ""}[model != ""])
						}
						if flags.asJSON {
							return flags.printJSON(cmd, docs)
						}
						w := cmd.OutOrStdout()
						for _, d := range docs {
							mark := " "
							if d.HasFile {
								mark = "*"
							}
							fmt.Fprintf(w, "%s %-12s %-12s %s (%s)\n", mark, d.DocType, d.Model, d.Title, d.URLName)
						}
						return nil
					}
					// Empty corpus, unfiltered auto: fall through to live.
				} else if flags.dataSource == "local" {
					// Local mode with no corpus: no network, honest empty.
					if flags.asJSON {
						return flags.printJSON(cmd, []any{})
					}
					fmt.Fprintln(cmd.ErrOrStderr(), "no documents in the corpus; run `averusa-pp-cli harvest` first")
					return nil
				}
			}

			// Fallback: fetch + parse the live sitemap (no corpus yet). The
			// sitemap is parsed so --json/--text work instead of dumping raw XML.
			if cliutil.IsVerifyEnv() {
				fmt.Fprintln(cmd.OutOrStdout(), "would fetch the support-portal article sitemap")
				return nil
			}
			ctxL, cancelL := boundCtx(cmd.Context(), flags)
			defer cancelL()
			c := averusa.New()
			names, err := c.ArticleNames(ctxL)
			if err != nil {
				return classifyAPIError(err, flags)
			}
			if limit > 0 && limit < len(names) {
				names = names[:limit]
			}
			entries := make([]map[string]any, 0, len(names))
			for _, n := range names {
				entries = append(entries, map[string]any{
					"url_name":  n,
					"title":     "",
					"doc_type":  "",
					"model":     "",
					"entity_id": "",
					"has_file":  false,
					"url":       "https://averusa.my.site.com/support/s/article/" + n,
				})
			}
			if flags.asJSON {
				return flags.printJSON(cmd, entries)
			}
			w := cmd.OutOrStdout()
			for _, e := range entries {
				fmt.Fprintf(w, "%s\n", e["url_name"])
			}
			return nil
		},
	}
	cmd.Flags().StringVar(&dbPath, "db", "", "corpus database path (default: CLI state dir)")
	cmd.Flags().StringVar(&docType, "type", "", "doc type filter: user-manual, spec-sheet, white-paper, quick-start, software, brochure, comparison-chart, article")
	cmd.Flags().StringVar(&model, "model", "", "model filter, e.g. cam570")
	cmd.Flags().IntVar(&limit, "limit", 0, "max results (default 100)")
	return cmd
}
